import{_ as p,a0 as o,w as r,s as d,ao as t,I as a,x as n,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"更多你所不知道的 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"更多你所不知道的 Linux 命令 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"更多你所不知道的 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"更多你所不知道的 Linux 命令 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20170413 More Unknown Linux Commands","title":"更多你所不知道的 Linux 命令","tag":"201712","desc":""},"relativePath":"201712/20170413 More Unknown Linux Commands.md","filePath":"[post].md"}'),u={name:"201712/20170413 More Unknown Linux Commands.md"};function m(c,s,g,k,b,f){const i=o("Link");return r(),d("div",null,[s[37]||(s[37]=t('<h1 id="更多你所不知道的-linux-命令" tabindex="-1">更多你所不知道的 Linux 命令 <a class="header-anchor" href="#更多你所不知道的-linux-命令" aria-label="Permalink to “更多你所不知道的 Linux 命令”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/outer-limits-of-linux.jpg?itok=5L5xfj2v" alt="unknown Linux commands" title="unknown Linux commands"></p><blockquote><p>在这篇文章中和 Carla Schroder 一起探索 Linux 中的一些鲜为人知的强大工具。</p></blockquote><p>本文是一篇关于一些有趣但鲜为人知的工具 <code>termsaver</code>、<code>pv</code> 和 <code>calendar</code> 的文章。<code>termsaver</code> 是一个终端 ASCII 屏保，<code>pv</code> 能够测量数据吞吐量并模拟输入。Debian 的 <code>calendar</code> 拥有许多不同的日历，并且你还可以制定你自己的日历。</p><h3 id="终端屏保" tabindex="-1">终端屏保 <a class="header-anchor" href="#终端屏保" aria-label="Permalink to “终端屏保”">​</a></h3><p>难道只有图形桌面能够拥有有趣的屏保吗？现在，你可以通过安装 <code>termsaver</code> 来享受 ASCII 屏保，比如 matrix（LCTT 译注：电影《黑客帝国》中出现的黑客屏保）、时钟、星球大战以及两个<ruby>不太安全<rt>not-safe-for-work</rt></ruby>（NSFW）的屏保。 NSFW 屏保还有很多。</p>',6)),a("p",null,[s[1]||(s[1]=a("code",null,"termsaver",-1)),s[2]||(s[2]=n(" 可以从 Debian/Ubuntu 的包管理器中直接下载安装，如果你使用别的不包含该软件包的发行版比如 CentOS，那么你可以从 ",-1)),e(i,{href:"http://termsaver.brunobraga.net/"},{default:l(()=>[...s[0]||(s[0]=[n("termsaver.brunobraga.net",-1)])]),_:1}),s[3]||(s[3]=n(" 下载，然后按照安装指导进行安装。",-1))]),s[38]||(s[38]=t(`<p>运行 <code>termsaver -h</code> 来查看一系列屏保：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> randtxt        displays word in random places on screen</span></span>
<span class="line"><span> starwars       runs the asciimation Star Wars movie</span></span>
<span class="line"><span> urlfetcher     displays url contents with typing animation</span></span>
<span class="line"><span> quotes4all     displays recent quotes from quotes4all.net</span></span>
<span class="line"><span> rssfeed        displays rss feed information</span></span>
<span class="line"><span> matrix         displays a matrix movie alike screensaver</span></span>
<span class="line"><span> clock          displays a digital clock on screen</span></span>
<span class="line"><span> rfc            randomly displays RFC contents</span></span>
<span class="line"><span> jokes4all      displays recent jokes from jokes4all.net (NSFW)</span></span>
<span class="line"><span> asciiartfarts  displays ascii images from asciiartfarts.com (NSFW)</span></span>
<span class="line"><span> programmer     displays source code in typing animation</span></span>
<span class="line"><span> sysmon         displays a graphical system monitor</span></span></code></pre></div><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/linux-commands-fig-1.png?itok=HveXXLLK" alt="Linux commands" title="Linux commands"></p><p><em>图片 1： 星球大战屏保。</em></p>`,4)),a("p",null,[s[5]||(s[5]=n("你可以通过运行命令 ",-1)),s[6]||(s[6]=a("code",null,"termsaver [屏保名]",-1)),s[7]||(s[7]=n(" 来使用屏保，比如 ",-1)),s[8]||(s[8]=a("code",null,"termsaver matrix",-1)),s[9]||(s[9]=n(" ，然后按 ",-1)),s[10]||(s[10]=a("code",null,"Ctrl+c",-1)),s[11]||(s[11]=n(" 停止。你也可以通过运行 ",-1)),s[12]||(s[12]=a("code",null,"termsaver [屏保名] -h",-1)),s[13]||(s[13]=n(" 命令来获取关于某一个特定屏保的信息。图片 1 来自 ",-1)),s[14]||(s[14]=a("code",null,"startwars",-1)),s[15]||(s[15]=n(" 屏保，它运行的是古老但受人喜爱的 ",-1)),e(i,{href:"http://www.asciimation.co.nz/"},{default:l(()=>[...s[4]||(s[4]=[n("Asciimation Wars",-1)])]),_:1}),s[16]||(s[16]=n(" 。",-1))]),s[39]||(s[39]=t(`<p>那些不太安全（NSFW）的屏保通过在线获取资源的方式运行，我并不喜欢它们，但好消息是，由于 <code>termsaver</code> 是一些 Python 脚本文件，因此，你可以很容易的利用它们连接到任何你想要的 RSS 资源。</p><h3 id="pv" tabindex="-1">pv <a class="header-anchor" href="#pv" aria-label="Permalink to “pv”">​</a></h3><p><code>pv</code> 命令是一个非常有趣的小工具但却很实用。它的用途是监测数据复制的过程，比如，当你运行 <code>rsync</code> 命令或创建一个 <code>tar</code> 归档的时候。当你不带任何选项运行 <code>pv</code> 命令时，默认参数为：</p><ul><li>-p ：进程</li><li>-t ：时间，到当前总运行时间</li><li>-e ：预计完成时间，这往往是不准确的，因为 <code>pv</code> 通常不知道需要移动的数据的大小</li><li>-r ：速率计数器，或吞吐量</li><li>-b ：字节计数器</li></ul><p>一次 <code>rsync</code> 传输看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -av /home/carla/ /media/carla/backup/ | pv </span></span>
<span class="line"><span>sending incremental file list</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>103GiB 0:02:48 [ 615MiB/s] [  &lt;=&gt;</span></span></code></pre></div><p>创建一个 tar 归档，就像下面这个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -czf - /file/path| (pv  &gt; backup.tgz)</span></span>
<span class="line"><span> 885MiB 0:00:30 [28.6MiB/s] [  &lt;=&gt;</span></span></code></pre></div><p><code>pv</code> 能够监测进程，因此也可以监测 Web 浏览器的最大活动，令人惊讶的是，它产生了如此多的活动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pv -d  3095                                                                                                             </span></span>
<span class="line"><span>  58:/home/carla/.pki/nssdb/key4.db:    0 B 0:00:33 </span></span>
<span class="line"><span>  [   0 B/s] [&lt;=&gt;                                                                           ] </span></span>
<span class="line"><span>  78:/home/carla/.config/chromium/Default/Visited Links:  </span></span>
<span class="line"><span>  256KiB 0:00:33 [   0 B/s] [&lt;=&gt;                                                      ] </span></span>
<span class="line"><span>  ] </span></span>
<span class="line"><span>  85:/home/carla/.con...romium/Default/data_reduction_proxy_leveldb/LOG:  </span></span>
<span class="line"><span>  298 B 0:00:33 [   0 B/s] [&lt;=&gt;                                       ]</span></span></code></pre></div><p>在网上，我偶然发现一个使用 <code>pv</code> 最有趣的方式：使用 <code>pv</code> 来回显输入的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;typing random stuff to pipe through pv&quot; | pv -qL 8</span></span>
<span class="line"><span>typing random stuff to pipe through pv</span></span></code></pre></div><p>普通的 <code>echo</code> 命令会瞬间打印一整行内容。通过管道传给 <code>pv</code> 之后能够让内容像是重新输入一样的显示出来。我不知道这是否有实际的价值，但是我非常喜欢它。<code>-L</code> 选项控制回显的速度，即多少字节每秒。</p><p><code>pv</code> 是一个非常古老且非常有趣的命令，这么多年以来，它拥有了许多的选项，包括有趣的格式化选项，多种输出选项，以及传输速度修改器。你可以通过 <code>man pv</code> 来查看所有的选项。</p><h3 id="usr-bin-calendar" tabindex="-1">/usr/bin/calendar <a class="header-anchor" href="#usr-bin-calendar" aria-label="Permalink to “/usr/bin/calendar”">​</a></h3><p>通过浏览 <code>/usr/bin</code> 目录以及其他命令目录和阅读 man 手册，你能够学到很多东西。在 Debian/Ubuntu 上的 <code>/usr/bin/calendar</code> 是 BSD 日历的一个变种，但它漏掉了月亮历和太阳历。它保留了多个日历包括 <code>calendar.computer, calendar.discordian, calendar.music</code> 以及 <code>calendar.lotr</code>。在我的系统上，man 手册列出了 <code>/usr/bin/calendar</code> 里存在的不同日历。下面这个例子展示了指环王日历接下来的 60 天：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ calendar -f /usr/share/calendar/calendar.lotr  -A 60</span></span>
<span class="line"><span>Apr 17  An unexpected party</span></span>
<span class="line"><span>Apr 23  Crowning of King Ellesar</span></span>
<span class="line"><span>May 19  Arwen leaves Lorian to wed King Ellesar</span></span>
<span class="line"><span>Jun 11  Sauron attacks Osgilliath</span></span></code></pre></div><p>这些日历是纯文本文件，因此，你可以轻松的创建你自己的日历。最简单的方式就是复制已经存在的日历文件的格式。你可以通过 <code>man calendar</code> 命令来查看创建个人日历文件的更详细的指导。</p><p>又一次很快走到了尽头。你可以花费一些时间来浏览你的文件系统，挖掘更多有趣的命令。</p>`,19)),a("p",null,[a("em",null,[s[18]||(s[18]=n("你可以通过来自 Linux 基金会和 edx 的免费课程 ",-1)),e(i,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:l(()=>[...s[17]||(s[17]=[n('"Introduction to Linux"',-1)])]),_:1}),s[19]||(s[19]=n(" 来学习更过关于 Linux 的知识",-1))]),s[20]||(s[20]=n("。",-1))]),a("p",null,[s[22]||(s[22]=n("（题图：",-1)),e(i,{href:"https://www.linux.com/licenses/category/creative-commons-zero"},{default:l(()=>[...s[21]||(s[21]=[n("CC Zero",-1)])]),_:1}),s[23]||(s[23]=n(" Pixabay）",-1))]),s[40]||(s[40]=a("hr",null,null,-1)),a("p",null,[s[25]||(s[25]=n("via: ",-1)),e(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/4/more-unknown-linux-commands"},{default:l(()=>[...s[24]||(s[24]=[n("https://www.linux.com/learn/intro-to-linux/2017/4/more-unknown-linux-commands",-1)])]),_:1})]),a("p",null,[s[29]||(s[29]=n("作者：",-1)),e(i,{href:"https://www.linux.com/users/cschroder"},{default:l(()=>[...s[26]||(s[26]=[n("CARLA SCHRODER",-1)])]),_:1}),s[30]||(s[30]=n(" 译者：",-1)),e(i,{href:"https://github.com/ucasFL"},{default:l(()=>[...s[27]||(s[27]=[n("ucasFL",-1)])]),_:1}),s[31]||(s[31]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[28]||(s[28]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[34]||(s[34]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[32]||(s[32]=[n("LCTT",-1)])]),_:1}),s[35]||(s[35]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...s[33]||(s[33]=[n("Linux中国",-1)])]),_:1}),s[36]||(s[36]=n(" 荣誉推出",-1))])])}const y=p(u,[["render",m]]);export{v as __pageData,y as default};
